module path_counter #(\n    parameter Y = 8,\n    parameter X = 16,\n    parameter MOD = 1000003\n) (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] x_init,\n    input [7:0] grid_flat [0:Y*X-1],\n    output reg [19:0] result,\n    output reg done\n);\n\n    // Character constants\n    localparam [7:0] CHAR_TILDE = 8'h7E;\n    localparam [7:0] CHAR_HASH = 8'h23;\n    localparam [7:0] CHAR_AT = 8'h40;\n    localparam [7:0] CHAR_GT = 8'h3E;\n    localparam [7:0] CHAR_LT = 8'h3C;\n\n    // State machine states\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] FIND_CASTLE = 3'd1;\n    localparam [2:0] INIT_DP = 3'd2;\n    localparam [2:0] PASS1 = 3'd3;\n    localparam [2:0] PASS2 = 3'd4;\n    localparam [2:0] NEXT_ROW = 3'd5;\n    localparam [2:0] OUTPUT = 3'd6;\n\n    reg [2:0] state, next_state;\n    reg [3:0] castle_x, castle_y;\n    reg [3:0] current_row;\n    reg [3:0] x_counter;\n    reg [19:0] dp_prev [0:X-1];\n    reg [19:0] dp_current [0:X-1];\n    reg [7:0] grid_reg [0:Y-1][0:X-1];\n    reg [19:0] temp_sum;\n    integer i, j;\n\n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: begin\n                if (start) next_state = FIND_CASTLE;\n            end\n            FIND_CASTLE: begin\n                if (castle_y == Y || (castle_x == X-1 && castle_y == Y-1)) begin\n                    next_state = INIT_DP;\n                end else begin\n                    next_state = FIND_CASTLE;\n                end\n            end\n            INIT_DP: begin\n                if (castle_y == Y-1) begin\n                    next_state = OUTPUT;\n                end else begin\n                    next_state = PASS1;\n                end\n            end\n            PASS1: begin\n                if (x_counter == 0) next_state = PASS2;\n                else next_state = PASS1;\n            end\n            PASS2: begin\n                if (x_counter == X-1) begin\n                    if (current_row == Y-1) next_state = OUTPUT;\n                    else next_state = NEXT_ROW;\n                end else begin\n                    next_state = PASS2;\n                end\n            end\n            NEXT_ROW: begin\n                next_state = PASS1;\n            end\n            OUTPUT: begin\n                next_state = IDLE;\n            end\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Datapath operations\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            castle_x <= 0;\n            castle_y <= 0;\n            current_row <= 0;\n            x_counter <= 0;\n            result <= 20'd0;\n            done <= 1'b0;\n            for (i = 0; i < X; i = i + 1) begin\n                dp_prev[i] <= 20'd0;\n                dp_current[i] <= 20'd0;\n            end\n            for (i = 0; i < Y; i = i + 1) begin\n                for (j = 0; j < X; j = j + 1) begin\n                    grid_reg[i][j] <= 8'd0;\n                end\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        for (i = 0; i < Y; i = i + 1) begin\n                            for (j = 0; j < X; j = j + 1) begin\n                                grid_reg[i][j] <= grid_flat[i * X + j];\n                            end\n                        end\n                        castle_x <= 0;\n                        castle_y <= 0;\n                        current_row <= 0;\n                    end\n                end\n                FIND_CASTLE: begin\n                    if (castle_x < X-1) begin\n                        castle_x <= castle_x + 1;\n                    end else begin\n                        castle_x <= 0;\n                        castle_y <= castle_y + 1;\n                    end\n                end\n                INIT_DP: begin\n                    for (i = 0; i < X; i = i + 1) begin\n                        dp_current[i] <= 20'd0;\n                    end\n                    dp_current[castle_x] <= 20'd1;\n                    x_counter <= X-1;\n                    current_row <= castle_y;\n                end\n                PASS1: begin\n                    if (grid_reg[current_row][x_counter] == CHAR_GT && x_counter < X-1) begin\n                        if (grid_reg[current_row][x_counter+1] != CHAR_HASH) begin\n                            temp_sum <= dp_current[x_counter] + dp_current[x_counter+1];\n                            if (temp_sum >= MOD) begin\n                                dp_current[x_counter] <= temp_sum - MOD;\n                            end else begin\n                                dp_current[x_counter] <= temp_sum;\n                            end\n                        end\n                    end\n                    x_counter <= x_counter - 1;\n                end\n                PASS2: begin\n                    if (grid_reg[current_row][x_counter] == CHAR_LT && x_counter > 0) begin\n                        if (grid_reg[current_row][x_counter-1] != CHAR_HASH) begin\n                            temp_sum <= dp_current[x_counter] + dp_current[x_counter-1];\n                            if (temp_sum >= MOD) begin\n                                dp_current[x_counter] <= temp_sum - MOD;\n                            end else begin\n                                dp_current[x_counter] <= temp_sum;\n                            end\n                        end\n                    end\n                    x_counter <= x_counter + 1;\n                end\n                NEXT_ROW: begin\n                    for (i = 0; i < X; i = i + 1) begin\n                        dp_prev[i] <= dp_current[i];\n                    end\n                    current_row <= current_row + 1;\n                    for (i = 0; i < X; i = i + 1) begin\n                        if (grid_reg[current_row][i] != CHAR_HASH && grid_reg[current_row-1][i] != CHAR_HASH) begin\n                            dp_current[i] <= dp_prev[i];\n                        end else begin\n                            dp_current[i] <= 20'd0;\n                        end\n                    end\n                    x_counter <= X-1;\n                end\n                OUTPUT: begin\n                    result <= dp_current[x_init];\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n\nendmodule